CREATE TABLE IF NOT EXISTS private.biz_reset_backups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reset_at timestamptz NOT NULL,reset_by uuid NOT NULL,counts jsonb NOT NULL,goals jsonb NOT NULL,goal_versions jsonb NOT NULL,goal_items jsonb NOT NULL,goal_events jsonb NOT NULL,documents jsonb NOT NULL,document_versions jsonb NOT NULL,document_events jsonb NOT NULL,document_views jsonb NOT NULL,late_requests jsonb NOT NULL,approval_runs jsonb NOT NULL,approval_events jsonb NOT NULL,notifications jsonb NOT NULL,push_deliveries jsonb NOT NULL);
REVOKE ALL ON private.biz_reset_backups FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.biz_reset_preview() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được reset dữ liệu Quản trị Kinh doanh'; END IF; RETURN jsonb_build_object('goals',(SELECT count(*) FROM public.biz_annual_goals),'goal_versions',(SELECT count(*) FROM public.biz_goal_versions),'goal_items',(SELECT count(*) FROM public.biz_goal_items),'goal_events',(SELECT count(*) FROM public.biz_goal_events),'plans',(SELECT count(*) FROM public.biz_documents WHERE kind='plan'),'reports',(SELECT count(*) FROM public.biz_documents WHERE kind='report'),'document_versions',(SELECT count(*) FROM public.biz_document_versions),'document_events',(SELECT count(*) FROM public.biz_document_events),'document_views',(SELECT count(*) FROM public.biz_document_views),'late_requests',(SELECT count(*) FROM public.biz_late_requests),'approval_runs',(SELECT count(*) FROM public.biz_approval_runs),'approval_events',(SELECT count(*) FROM public.biz_approval_events),'notifications',(SELECT count(*) FROM public.notifications WHERE kind IN ('biz_submitted','biz_approved','biz_returned') OR dedup_key LIKE 'biz-run:%'),'le_minh_ngoc',(SELECT (SELECT count(*) FROM public.biz_documents d JOIN public.profiles p ON p.id=d.user_id WHERE p.full_name ILIKE '%Lê Minh Ngọc%')+(SELECT count(*) FROM public.biz_annual_goals g JOIN public.profiles p ON p.id=g.user_id WHERE p.full_name ILIKE '%Lê Minh Ngọc%')),'backups',(SELECT count(*) FROM private.biz_reset_backups)); END; $$;
CREATE OR REPLACE FUNCTION public.biz_reset_execute(_confirm text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE me uuid:=auth.uid(); ts timestamptz; c jsonb; bid uuid; BEGIN IF NOT public.is_super_admin(me) THEN RAISE EXCEPTION 'Chỉ Super Admin được reset dữ liệu Quản trị Kinh doanh'; END IF; IF _confirm IS DISTINCT FROM 'RESET KINH DOANH' THEN RAISE EXCEPTION 'Nhập đúng RESET KINH DOANH để xác nhận'; END IF; PERFORM pg_advisory_xact_lock(841927306); LOCK TABLE public.biz_annual_goals,public.biz_goal_versions,public.biz_goal_items,public.biz_goal_events,public.biz_documents,public.biz_document_versions,public.biz_document_events,public.biz_document_views,public.biz_late_requests,public.biz_approval_runs,public.biz_approval_events IN SHARE ROW EXCLUSIVE MODE; ts:=clock_timestamp(); c:=jsonb_build_object('goals',(SELECT count(*) FROM public.biz_annual_goals),'goal_versions',(SELECT count(*) FROM public.biz_goal_versions),'goal_items',(SELECT count(*) FROM public.biz_goal_items),'goal_events',(SELECT count(*) FROM public.biz_goal_events),'plans',(SELECT count(*) FROM public.biz_documents WHERE kind='plan'),'reports',(SELECT count(*) FROM public.biz_documents WHERE kind='report'),'document_versions',(SELECT count(*) FROM public.biz_document_versions),'document_events',(SELECT count(*) FROM public.biz_document_events),'document_views',(SELECT count(*) FROM public.biz_document_views),'late_requests',(SELECT count(*) FROM public.biz_late_requests),'approval_runs',(SELECT count(*) FROM public.biz_approval_runs),'approval_events',(SELECT count(*) FROM public.biz_approval_events),'notifications',(SELECT count(*) FROM public.notifications WHERE kind IN ('biz_submitted','biz_approved','biz_returned') OR dedup_key LIKE 'biz-run:%')); INSERT INTO private.biz_reset_backups(reset_at,reset_by,counts,goals,goal_versions,goal_items,goal_events,documents,document_versions,document_events,document_views,late_requests,approval_runs,approval_events,notifications,push_deliveries) VALUES(ts,me,c,coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_annual_goals t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_goal_versions t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_goal_items t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_goal_events t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_documents t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_document_versions t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_document_events t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_document_views t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_late_requests t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_approval_runs t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.biz_approval_events t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(n)) FROM public.notifications n WHERE n.kind IN ('biz_submitted','biz_approved','biz_returned') OR n.dedup_key LIKE 'biz-run:%'),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM public.push_deliveries d JOIN public.notifications n ON n.id=d.notification_id WHERE n.kind IN ('biz_submitted','biz_approved','biz_returned') OR n.dedup_key LIKE 'biz-run:%'),'[]')) RETURNING id INTO bid; DELETE FROM public.push_deliveries d USING public.notifications n WHERE n.id=d.notification_id AND (n.kind IN ('biz_submitted','biz_approved','biz_returned') OR n.dedup_key LIKE 'biz-run:%'); DELETE FROM public.notifications WHERE kind IN ('biz_submitted','biz_approved','biz_returned') OR dedup_key LIKE 'biz-run:%'; DELETE FROM public.biz_approval_events WHERE id IS NOT NULL; DELETE FROM public.biz_approval_runs WHERE id IS NOT NULL; DELETE FROM public.biz_late_requests WHERE id IS NOT NULL; DELETE FROM public.biz_document_views WHERE id IS NOT NULL; DELETE FROM public.biz_document_events WHERE id IS NOT NULL; UPDATE public.biz_documents SET official_version_id=NULL; DELETE FROM public.biz_document_versions WHERE id IS NOT NULL; DELETE FROM public.biz_documents WHERE id IS NOT NULL; DELETE FROM public.biz_goal_events WHERE id IS NOT NULL; DELETE FROM public.biz_goal_items WHERE id IS NOT NULL; UPDATE public.biz_annual_goals SET official_version_id=NULL; DELETE FROM public.biz_goal_versions WHERE id IS NOT NULL; DELETE FROM public.biz_annual_goals WHERE id IS NOT NULL; RETURN jsonb_build_object('reset_at',ts,'backup_id',bid,'counts',c); END; $$;
REVOKE ALL ON FUNCTION public.biz_reset_preview() FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.biz_reset_execute(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.biz_reset_preview() TO authenticated;
GRANT EXECUTE ON FUNCTION public.biz_reset_execute(text) TO authenticated;